   if(/^\/api\/(pc|storage|files|materials)\b/.test(route)||['/api/timenet/check-sheet','/api/settings/import-source','/api/timenet/refresh'].includes(route))throw Error('v2.0에서 제거된 서버·PC 연결 기능입니다. 학생은 직접 등록 또는 엑셀 붙여넣기로 등록해 주세요.');
