   if(route==='/api/parents/create'){body.login_id=normalizeID(body.login_id);if(!body.name||!/^0\d{8,10}$/.test(String(body.phone||'').replace(/\D/g,'')))throw Error('학부모 이름과 전화번호를 확인해 주세요.');}
   if(route.endsWith('/password')&&body.action==='reset'&&!body.new)throw Error('새 비밀번호를 입력해 주세요.');
