async function localAPI(path,options={}){
 const u=new URL(path,'https://browser.invalid'),r=u.pathname,d=options.body||{},a=localIdentity(),child=localActor();
 const teachingResult=await localTeachingAPI(r,d,options,a);if(teachingResult!==undefined)return teachingResult;
 const parentList=()=>D.parents.map(p=>({...p,children:D.students.filter(x=>x.parent_id===p.id)}));
 if(r==='/api/me')return clone(a);
 if(r==='/api/bootstrap'){
  const sc=localScope(),students=a.role==='parent'?D.students.filter(x=>x.parent_id===a.id&&x.active!==false):a.role==='admin'?D.students:D.students.filter(x=>sc.enrollments.some(e=>e.student_id===x.id));
  const ps=a.role==='parent'?[]:D.parents.filter(p=>students.some(x=>x.parent_id===p.id));
  return clone({user:{...a,...(a.role==='parent'?{selected_student_id:child.id}:{})},...sc,students,parents:ps,teachers:D.accounts.map(x=>({id:x.id,name:x.name,status:x.status})),selected_student_id:a.role==='parent'?child.id:'',timenet_meta:a.role==='parent'?{}:D.timenet_meta});
 }
 if(r==='/api/parents'){
  const scoped=localScope();return clone({rows:a.role==='admin'?parentList():parentList().map(p=>({...p,children:p.children.filter(x=>scoped.enrollments.some(e=>e.student_id===x.id))})).filter(p=>p.children.length)});
 }
 if(r==='/api/parents/search'){const q=(u.searchParams.get('q')||'').toLowerCase();return clone({rows:D.parents.filter(p=>p.login_id.toLowerCase()===q||p.phone===q.replace(/\D/g,''))})}
 if(/^\/api\/students\/[^/]+\/parent$/.test(r)){
  const student=D.students.find(x=>x.id===r.split('/')[3]);if(!student)throw Error('학생을 찾을 수 없습니다.');
  if(options.method==='POST'){
   if((student.parent_id||null)!==(d.expected_parent_id||null))throw Error('다른 사용자가 배정을 변경했습니다.');
   if(student.parent_id&&student.parent_id!==d.parent_id&&!d.confirmed)throw Error('기존 학부모 배정 변경을 확인해 주세요.');
   const p=D.parents.find(x=>x.id===d.parent_id&&x.status==='active');if(!p)throw Error('사용할 수 없는 학부모 계정입니다.');
   if(student.parent_id!==p.id){D.parentHistory.push({id:uid(),student_id:student.id,previous_parent_id:student.parent_id,next_parent_id:p.id,actor_id:a.id,created_at:new Date().toISOString()});student.parent_id=p.id;student.version++}return{ok:true,parent_id:p.id};
  }
  const p=D.parents.find(p=>p.id===student.parent_id)||null;return clone({student,parent:p,...(a.role==='admin'?{children:D.students.filter(x=>p&&x.parent_id===p.id),history:D.parentHistory.filter(x=>x.student_id===student.id),password_available:!!p}:{})});
 }
 if(r==='/api/parents/create'){
  const id=String(d.login_id||'').normalize('NFKC').trim().toLowerCase();if([...D.accounts,...D.parents].some(x=>x.login_id.toLowerCase()===id))throw Error('이미 사용 중인 아이디입니다.');
  const student=D.students.find(x=>x.id===d.student_id);
  if(student&&(student.parent_id||null)!==(d.expected_parent_id||null))throw Error('학부모 배정이 변경되었습니다.');
  if(student?.parent_id&&!d.confirmed)throw Error('기존 배정 변경을 확인해 주세요.');
  const p={id:uid(),login_id:id,name:d.name,phone:d.phone.replace(/\D/g,''),status:'active',version:1,created_at:new Date().toISOString()};D.parents.push(p);D.parentPasswords[p.id]=d.password||p.phone.slice(-4);if(student){student.parent_id=p.id;student.version++}return clone({ok:true,parent:p});
 }
 if(/^\/api\/parents\/[^/]+\/edit$/.test(r)){
  if(a.role!=='admin')throw Error('최종관리자 권한이 필요합니다.');const p=D.parents.find(x=>x.id===r.split('/')[3]);if(!p||p.version!==d.version)throw Error('다시 불러와 주세요.');
  if([...D.accounts,...D.parents].some(x=>x.id!==p.id&&x.login_id.toLowerCase()===d.login_id.toLowerCase()))throw Error('중복 아이디입니다.');Object.assign(p,d,{version:p.version+1});return clone({ok:true,parent:p});
 }
 if(/^\/api\/parents\/[^/]+\/password$/.test(r)){
  if(a.role!=='admin')throw Error('최종관리자 권한이 필요합니다.');if(d.admin_password!==D.accounts.find(x=>x.id===a.id)?.password)throw Error('관리자 비밀번호가 일치하지 않습니다.');const id=r.split('/')[3];
  if(d.action==='reset'){D.parentPasswords[id]=d.new;return{ok:true}}
  D.audit.push({id:uid(),actor_id:a.id,action:'password_view',entity:'mp_parents',record_id:id,fields:[],created_at:new Date().toISOString()});return{available:true,password:D.parentPasswords[id]||''};
 }
 return localLegacyAPI(path,options);
}

