const DEFAULT_DESIGN={academy_name:C.BRAND||'미래탐구',eyebrow:'미래탐구 학습 관리실',headline:'오늘의 수업,\n내일의 가능성.',description:'수업 안내부터 학습 기록까지.\n학생과 학부모, 선생님이 함께 확인합니다.',form_title:'클래스룸 로그인',form_subtitle:'등록된 아이디로 접속해 주세요.',footer:'아이디와 비밀번호 문의는 담당 선생님께 연락해 주세요.',dashboard_headline:'오늘의 학습 기록',dashboard_note:'수업과 학생 소식을 확인해 주세요.',buttons:[],accent:'sage',alignment:'left',layout:'split'};
