function loginMarkup(d=loginDesign,preview=false){return `<div class="login-layout ${preview?'design-preview':''}" data-layout="${d.layout}" data-align="${d.alignment}"><section class="login-brand"><div class="logo">${mark}<div><strong data-login-copy="academy_name">${esc(d.academy_name)}</strong><small>학습 관리실</small></div></div><div class="login-story"><div class="eyebrow" data-login-copy="eyebrow">${esc(d.eyebrow)}</div><h1 data-login-copy="headline">${esc(d.headline)}</h1><p data-login-copy="description">${esc(d.description)}</p><div class="learning-signature" aria-hidden="true"><span class="signature-point first"></span><div class="signature-path"></div><span class="signature-point second"></span><span class="signature-point third"></span><div class="signature-caption">EVERY STEP, TOGETHER</div></div></div><div class="brand-bottom"><span class="fine-rule"></span><small>CARE IN EVERY DETAIL</small></div></section><section class="login-side"><div class="login-form"><div class="mobile-logo">${mark}<strong data-login-copy="academy_name">${esc(d.academy_name)}</strong></div><div class="eyebrow">YOUR CLASSROOM</div><h2 data-login-copy="form_title">${esc(d.form_title)}</h2><p class="subtitle" data-login-copy="form_subtitle">${esc(d.form_subtitle)}</p><form ${preview?'class="preview-form"':'id="login-form"'}>${fieldsHtml([{key:'name',label:'아이디',placeholder:'학부모 또는 강사 아이디',required:true,wide:true,maxlength:100},{key:'password',label:'비밀번호',type:'password',required:true,wide:true,maxlength:200}])}<div class="inline-error hidden" id="${preview?'preview-error':'login-error'}" role="alert"></div><button type="${preview?'button':'submit'}" class="btn primary login-submit"><span class="login-button-label">로그인</span><span class="login-button-icon">${icon('arrow')}</span></button><div class="login-activity" ${preview?'':'id="login-activity"'} role="status" aria-live="polite" hidden><span class="activity-orb"></span><div><strong>접속 정보를 확인하고 있습니다.</strong><small>잠시만 기다려 주세요.</small></div></div></form><small class="login-foot" data-login-copy="footer">${esc(d.footer)}</small>${!preview&&DEMO?btn('예시 화면으로 돌아가기','demo-login','','ghost'):''}</div></section></div>`}
