function reassignConsent(student,parentId,currentId){
 if(!currentId||parentId===currentId)return true;
 return confirm(`${student.name} 학생은 이미 배정된 학부모가 있습니다. 그래도 새로운 학부모에게 배정하시겠습니까?\n\n변경하면 기존 학부모는 이 학생의 자료를 볼 수 없고, 새 학부모는 지난 수강 기록까지 볼 수 있습니다. 다른 형제의 배정은 바뀌지 않습니다.`);
}
