async function start(){if(!window.MiraeStore.configured()){renderSetupNotice();return}if(!S.token){renderLogin();return}$('#app').innerHTML=`<div class="initial-loader">${mark}<span>클래스룸에 연결하고 있습니다.</span></div>`;try{const r=await api('/api/workspace?'+new URLSearchParams({start:S.start,end:S.end}));S.base=r.base;S.user=r.base.user;S.studentId=r.base.selected_student_id||'';S.data=r.data;S.classId=r.class_id||'';if(r.data.range){S.start=r.data.range.start;S.end=r.data.range.end}render();fetchLoginDesign();window.MiraePC?.auto()}catch(e){S.token='';store.del('mirae-v2-session');renderLogin();toast(e.message,true)}}
function openMswitchLink(message=''){if(isFamily())return;const existing=$('#mswitch-link-root');if(existing){if(message)existing.querySelector('.msw-result').textContent=message;return}modal('개인설정 · 엠스위치 연동','<div id="mswitch-link-root"></div>',btn('닫기','close-modal'),{wide:true});window.MiraeSMS?.mountLink($('#mswitch-link-root'),message)}
function canEditDesign(a=S.user){return !!a&&(a.role==='admin'||a.role==='teacher'&&a.can_edit_login===true)}
function canUsePC(){return true}
function startPresence(){window.MiraePC?.paint()}
function stopPresence(){window.MiraePC?.reset()}
function resetEasyPC(){}
function updatePCIndicator(){window.MiraePC?.paint()}
