 const textFields=[['academy_name','학원명'],['eyebrow','안내 분류 · 짧은 문구'],['headline','로그인 화면 대표 문구'],['description','로그인 화면 설명'],['form_title','로그인 제목'],['form_subtitle','로그인 안내'],['footer','문의 안내'],['dashboard_headline','로그인 후 메인 제목'],['dashboard_note','로그인 후 메인 안내']].map(([key,label])=>({key,label,maxlength:240,wide:true,type:['headline','description','dashboard_note'].includes(key)?'textarea':'text',rows:2}));
 node.innerHTML=head('로그인 화면','문구와 링크는 모든 접속자에게 적용됩니다. 편집 권한은 강사 · 권한에서 지정합니다.',btn('변경 저장','design-save','','primary','check'))+`<div class="design-editor"><form id="design-form" class="design-controls"><h2>화면 문구</h2>${fieldsHtml([...textFields,{key:'accent',label:'강조색',type:'select',options:[['sage','차분한 녹색'],['blue','남색'],['ink','회청색'],['sand','갈색']]},{key:'alignment',label:'문구 정렬',type:'select',options:[['left','왼쪽'],['center','가운데']]},{key:'layout',label:'화면 구성',type:'select',wide:true,options:[['split','안내와 로그인 나란히'],['center','로그인 중심']]}],draft)}<section class="promotion-editor"><h2>홍보 버튼 <small id="promo-counter"></small></h2><p>특강 · 강좌 · 학원 소식으로 연결합니다. 주소는 https://부터 입력하세요.</p><div id="promo-fields"></div><button type="button" class="btn" id="promo-add">홍보 버튼 추가</button></section></form><section class="design-live"><div class="design-live-label">미리보기 <small>변경 저장을 누르면 반영됩니다.</small></div><div id="design-live-canvas"></div><div id="design-save-status" role="status" aria-live="polite"></div></section></div>`;
 const form=$('#design-form'),canvas=$('#design-live-canvas');form.onsubmit=e=>e.preventDefault();
