 function draw(){const values={};for(const x of form.elements)if(x.name)values[x.name]=x.value;draft={...values,buttons:links};canvas.innerHTML=loginMarkup(safeDesign(draft),true);canvas.dataset.tone=values.accent;fitLoginPreview(canvas);$$('input,button',canvas).forEach(x=>{x.disabled=true;x.tabIndex=-1});$$('a',canvas).forEach(x=>{x.tabIndex=-1;x.onclick=e=>e.preventDefault()})}
 function renderLinks(){const box=$('#promo-fields');box.innerHTML=links.map((b,i)=>`<div class="promo-edit-row"><div class="promo-edit-number">${i+1}</div><div class="promo-edit-fields"><label>버튼 이름<input data-promo-label maxlength="40" value="${esc(b.label)}" placeholder="예: 겨울방학 과학 특강"></label><label>연결 주소<input data-promo-url type="url" value="${esc(b.url)}" placeholder="https://..."></label></div><div class="promo-edit-tools"><button type="button" class="btn ghost" data-promo-up="${i}" ${i===0?'disabled':''} aria-label="${i+1}번 버튼 위로">↑</button><button type="button" class="btn ghost" data-promo-remove="${i}" aria-label="${i+1}번 버튼 삭제">삭제</button></div></div>`).join('');$('#promo-counter').textContent=links.length+' / 6';$('#promo-add').disabled=links.length>=6;$$('[data-promo-remove]',box).forEach(b=>b.onclick=()=>{collectLinks();links.splice(+b.dataset.promoRemove,1);renderLinks();draw()});$$('[data-promo-up]',box).forEach(b=>b.onclick=()=>{collectLinks();const i=+b.dataset.promoUp;[links[i-1],links[i]]=[links[i],links[i-1]];renderLinks();draw()})}
 $('#promo-add').onclick=()=>{collectLinks();if(links.length>=6)return;links.push({label:'',url:''});renderLinks();draw();$$('[data-promo-label]',form).at(-1).focus()};form.addEventListener('input',()=>{collectLinks();draw()});form.addEventListener('change',()=>{collectLinks();draw()});renderLinks();draw();
 $('[data-action=design-save]',node).onclick=async()=>{const b=$('[data-action=design-save]',node);if(b.disabled)return;collectLinks();draw();b.disabled=true;try{validateDesign(draft);const r=await api('/api/admin/login-design',{method:'POST',body:{design:draft,revision}});revision=r.revision;loginDesign=safeDesign(r.design);designRevision=revision;themeDesign();$('#design-save-status').textContent='저장했습니다. 로그인 화면과 메인화면에 적용됩니다.';toast('화면 설정을 저장했습니다.')}catch(e){$('#design-save-status').textContent=e.message;toast(e.message,true)}finally{b.disabled=false}};
